<template><view class="page"><AppTopbar title="自测"/><view class="intro">上传高远球或步法短视频，获取能力标签和训练建议。</view><VideoUploadCard v-if="status==='idle'||status==='error'" @choose="chooseVideo"/><text v-if="error" class="error">{{error}}</text><view v-if="status==='processing'" class="card"><text class="title">正在分析 {{videoName}}</text><text class="detail">{{videoMeta}} · 正在提取姿态关键点，请稍候</text><view class="progress"><view/></view></view><view v-if="status==='success'&&result" class="card result"><view class="result-head"><text class="title">测评结果</text><text v-if="restored" class="restored">已从本地缓存恢复</text></view><text class="detail">{{videoName}} · 综合水平 {{result.level}} · 平均 {{result.scoreAverage}} 分</text><view class="source"><text>结果来源：{{result.sourceLabel}}</text><text>置信度：{{result.confidence}}（{{result.confidenceLabel}}）</text></view><view v-for="item in result.scores" :key="item.name"><ScoreBar :label="item.name" :value="item.value"/><text class="issue">{{item.issue}}</text><text class="evidence">依据：{{item.evidence}}</text></view><TagList :tags="result.tags"/><AdviceCard title="训练建议" :text="result.advice"/><text class="basis">{{result.basis}}</text><view class="limits"><text class="limit-title">使用边界</text><text v-for="item in result.limitations" :key="item" class="limit">{{item}}</text></view><text class="disclaimer">测评仅供训练和匹配参考，不作为专业运动诊断。</text><button v-if="!result.confirmed" class="primary" @tap="confirmResult">确认并保存</button><button v-else class="secondary" @tap="retry">再测一次</button></view></view></template>
<script setup>
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppTopbar from '../../components/AppTopbar.vue';import VideoUploadCard from '../../components/VideoUploadCard.vue';import ScoreBar from '../../components/ScoreBar.vue';import AdviceCard from '../../components/AdviceCard.vue';import TagList from '../../components/TagList.vue';import {requireLogin} from '../../utils/auth';import {loadLastReport,saveProfile,saveReport} from '../../utils/storage';import {createFallbackAnalysis,decorateReport,validateVideo} from '../../utils/analysis';import {callCloud} from '../../utils/cloud';
const status=ref('idle'),videoName=ref(''),videoMeta=ref(''),result=ref(null),error=ref(''),restored=ref(false);const profileDefault={nickname:'羽球新人',region:'武汉',availability:'周末晚上',level:'待测评',tags:['等待首次测评']};onShow(()=>{if(!requireLogin())return;if(status.value==='idle'&&!result.value){const old=loadLastReport();if(old){result.value=decorateReport(old);status.value='success';videoName.value=old.video?.name||'';restored.value=true}}});function chooseVideo(){uni.chooseVideo({sourceType:['album','camera'],compressed:false,maxDuration:60,camera:'back',success:file=>{const v=validateVideo(file);if(!v.ok){status.value='error';error.value=v.message;return}status.value='processing';error.value='';videoName.value=v.meta.name;videoMeta.value=`${Math.round(v.meta.size/1024/1024*10)/10||'<0.1'}MB · ${v.meta.duration||0}秒`;setTimeout(()=>{result.value=decorateReport(createFallbackAnalysis(v.meta));status.value='success'},900)},fail:()=>{status.value='idle'}})}function confirmResult(){if(!result.value)return;const next={...result.value,confirmed:true,confirmedAt:new Date().toISOString()};saveReport(next);saveProfile({...uni.getStorageSync('badminton_friend_profile'),level:next.level,tags:next.tags});callCloud('saveAssessment',{report:next}).catch(()=>{});result.value=decorateReport(next);uni.showToast({title:'已保存到我的资料',icon:'success'})}function retry(){status.value='idle';result.value=null;error.value='';restored.value=false}
</script>
<style scoped>.page{padding-bottom:40rpx}.intro{padding:28rpx 32rpx 20rpx;color:#666;line-height:1.6}.card{margin:20rpx 24rpx 0;padding:32rpx;border-radius:14rpx;background:#fff}.title{display:block;font-size:32rpx;font-weight:700}.detail,.error,.issue,.evidence,.basis,.disclaimer{display:block;margin-top:12rpx;color:#777;font-size:23rpx;line-height:1.6}.error{margin:20rpx 32rpx;color:#fa5151}.progress{height:12rpx;margin-top:30rpx;background:#eee}.progress view{height:100%;width:65%;background:#07c160}.result-head{display:flex;justify-content:space-between}.restored{color:#07c160;font-size:22rpx}.source{margin-top:16rpx;padding:16rpx;color:#607067;background:#f5faf7;font-size:23rpx;line-height:1.7}.limits{margin-top:22rpx;padding:20rpx;background:#fff9e6;border-radius:8rpx}.limit-title,.limit{display:block}.limit-title{color:#806b2b;font-weight:600}.limit{margin-top:8rpx;color:#806b2b;font-size:22rpx}.primary,.secondary{margin-top:26rpx;height:86rpx;line-height:86rpx;border-radius:8rpx}.primary{color:#fff;background:#07c160}.secondary{color:#07c160;background:#fff;border:1rpx solid #07c160}</style>
